root = Path(__file__).resolve().parents[1] if "__file__" in globals() else Path(P["root"]).parent
source = '"""Frozen serial inference and separate native stress with trained weights."""\n\nimport copy\nimport gc\nimport hashlib\nfrom pathlib import Path\nimport statistics\nimport time\n\nimport gorilla\nimport numpy as np\nimport torch\nfrom ipdn.dataset import build_dataset\nfrom ipdn.utils import get_root_logger\nfrom train import resolve_model_class\n\nroot = Path(P["root"])\nassert (root / ".codex_source_commit").read_text().strip() == "5f2489de78196e8d89c004e452a665c0946f2a94"\nassert not Path("/proc/66677").exists()\nassert not subprocess.check_output([\n    "nvidia-smi", "-i", "1", "--query-compute-apps=pid", "--format=csv,noheader,nounits"\n]).decode().strip(), "GPU1 has a compute process"\nsource_manifest = [\n    ("ipdn/model_paper5/adares_y31_mask_shape/__init__.py", "8014a039f2388c8ca57692438985474724a17785186036e5208771b856072722"),\n    ("ipdn/model_paper5/adares_y31_mask_shape/backbone.py", "1eb4ac3483961e708c23b0abad396c181dbf38c56fcca559d88b9622af46bafd"),\n    ("ipdn/model_paper5/adares_y31_mask_shape/dec.py", "97c29b048b2ee67977cf0112668ab6a1d616445a0b55ef680c4c7803afa055c1"),\n    ("ipdn/model_paper5/adares_y31_mask_shape/ipdn.py", "63c8f30bda20300d98d3d9a8a6478fc1a841cbaa3b334ee71688711e06375d97"),\n    ("ipdn/model_paper5/adares_y31_mask_shape/loss.py", "4aa2818948ebfd9fe416b3b310a053384508ef92c3b67831833fece560523084"),\n    ("ipdn/model_paper5/adares_y31_mask_shape/sample_model.py", "03fd683acc6d49d9b53e634b42bd150a3259a1a15c7dc8fe2badf115870a345b"),\n    ("configs_song/model_paper5/adares_y31_mask_shape_res.yaml", "1a170434f63da98e10f59c5b17473cde5cf3ff6be0e4381e2771f322853ffa03"),\n]\nassert all(hashlib.sha256((root / path).read_bytes()).hexdigest() == expected\n           for path, expected in source_manifest)\ncaptures = {\n    name: json.loads(Path("/tmp/adares_y31_" + mode + "_" + P["token"] + ".json").read_text())\n    for name, mode in (("candidate", "y31"), ("parent", "w2"))\n}\nassert all(c["complete"] and c["completed_passes"] == 2 for c in captures.values())\ncfg = gorilla.Config.fromfile(captures["candidate"]["config"])\ntorch.set_num_threads(4)\n\n\ndef load_trained(name):\n    capture = captures[name]\n    digest = hashlib.sha256()\n    with open(capture["checkpoint"], "rb") as stream:\n        for block in iter(lambda: stream.read(8 * 1024 * 1024), b""):\n            digest.update(block)\n    assert digest.hexdigest() == capture["checkpoint_sha256"]\n    gorilla.set_random_seed(1999)\n    model = resolve_model_class(capture["config"])(**cfg.model).cuda()\n    checkpoint = torch.load(capture["checkpoint"], map_location="cpu")\n    loaded = model.load_state_dict(checkpoint["model"], strict=False)\n    assert not loaded.missing_keys and not set(loaded.unexpected_keys) - {\n        "text_encoder.embeddings.position_ids", "text_encoder.embeddings.token_type_ids"}\n    del checkpoint\n    return model\n\n\ndata_cfg = cfg.data.train.copy()\ndata_cfg.training = False\ndata_cfg.aug = False\ndata_cfg.with_elastic = False\ngorilla.set_random_seed(1999)\ndataset = build_dataset(data_cfg, get_root_logger())\nindices, seen = [], set()\nfor index, chunk in enumerate(dataset.scene_inputs):\n    if chunk[0]["scene_id"] not in seen:\n        seen.add(chunk[0]["scene_id"])\n        indices.append(index)\n    if len(indices) == 8:\n        break\nindices += [728, 6780]\nbatches = [dataset.collate_fn([dataset[index]]) for index in indices]\nassert [batch["scan_ids"] for batch in batches[-2:]] == [["scene0054_00"], ["scene0497_00"]]\nrows, parameters = {}, {}\nfor name in ("candidate", "parent"):\n    model = load_trained(name)\n    model.eval()\n    parameters[name] = sum(parameter.numel() for parameter in model.parameters())\n    readings = []\n    with torch.no_grad():\n        for index, batch in zip(indices, batches):\n            for _ in range(2):\n                gorilla.set_random_seed(1999)\n                model(batch, mode="predict")\n            samples = []\n            for _ in range(3):\n                gc.collect()\n                torch.cuda.empty_cache()\n                torch.cuda.synchronize()\n                torch.cuda.reset_peak_memory_stats()\n                gorilla.set_random_seed(1999)\n                start = time.monotonic()\n                prediction = model(batch, mode="predict")\n                torch.cuda.synchronize()\n                samples.append(dict(seconds=time.monotonic() - start,\n                                    peak_allocated_gib=torch.cuda.max_memory_allocated() / 2**30,\n                                    peak_reserved_gib=torch.cuda.max_memory_reserved() / 2**30))\n                assert all(value.shape[0] == 128 for value in prediction["indi"])\n                assert all(value.numel() == len(batch["superpoints"]) for value in prediction["pred_pmask"])\n            readings.append(dict(scan_ids=batch["scan_ids"], dataset_index=index,\n                                 points=len(batch["superpoints"]), readings=samples))\n    rows[name] = readings\n    del model, prediction\n    gc.collect()\n    torch.cuda.empty_cache()\nassert parameters == {"candidate": 164763271, "parent": 164629637}\ndel batches, dataset\ngorilla.set_random_seed(1999)\ndataset = build_dataset(cfg.data.train.copy(), get_root_logger())\nstress_batches = [\n    dataset.collate_fn([dataset[index] for index in indices[:2]]),\n    dataset.collate_fn([dataset[728], dataset[6780]]),\n]\nstress = {}\nfor name in ("candidate", "parent"):\n    model = load_trained(name)\n    model.train()\n    optimizer = gorilla.build_optimizer(model, copy.deepcopy(cfg.optimizer))\n\n    def step(batch):\n        optimizer.zero_grad(set_to_none=True)\n        loss, _ = model(batch, mode="loss")\n        assert torch.isfinite(loss)\n        loss.backward()\n        assert all(torch.isfinite(parameter.grad).all()\n                   for parameter in model.parameters() if parameter.grad is not None)\n        torch.nn.utils.clip_grad_norm_(model.parameters(), cfg.train.grad_clip)\n        optimizer.step()\n        return float(loss)\n\n    readings = []\n    for batch in stress_batches:\n        for _ in range(2):\n            step(batch)\n        samples = []\n        for _ in range(3):\n            optimizer.zero_grad(set_to_none=True)\n            gc.collect()\n            torch.cuda.empty_cache()\n            torch.cuda.synchronize()\n            torch.cuda.reset_peak_memory_stats()\n            start = time.monotonic()\n            loss = step(batch)\n            torch.cuda.synchronize()\n            samples.append(dict(seconds=time.monotonic() - start, loss=loss,\n                                peak_allocated_gib=torch.cuda.max_memory_allocated() / 2**30,\n                                peak_reserved_gib=torch.cuda.max_memory_reserved() / 2**30))\n        readings.append(dict(scan_ids=batch["scan_ids"], points=len(batch["superpoints"]), readings=samples))\n    stress[name] = readings\n    del optimizer, model\n    gc.collect()\n    torch.cuda.empty_cache()\nsummary = {}\nfor name, value in rows.items():\n    summary[name] = {}\n    for group, chosen in (("train8", value[:8]), ("largest_pair", value[-2:])):\n        samples = [sample for row in chosen for sample in row["readings"]]\n        seconds = [sample["seconds"] for sample in samples]\n        summary[name][group] = dict(\n            median_seconds=statistics.median(seconds),\n            descriptive_p95_seconds=float(np.percentile(seconds, 95)),\n            peak_allocated_gib=max(sample["peak_allocated_gib"] for sample in samples),\n            peak_reserved_gib=max(sample["peak_reserved_gib"] for sample in samples))\n    samples = stress[name][-1]["readings"]\n    summary[name]["native_train_stress"] = dict(\n        median_seconds=statistics.median(sample["seconds"] for sample in samples),\n        peak_allocated_gib=max(sample["peak_allocated_gib"] for sample in samples),\n        peak_reserved_gib=max(sample["peak_reserved_gib"] for sample in samples))\nresult = dict(complete=True, id="AdaRES-Y31", manifest_indices=indices,\n              source_files=[dict(path=path, sha256=sha) for path, sha in source_manifest],\n              parameters=parameters, available_queries=128, selected_queries=1,\n              gpu_precheck=dict(memory_mib=used, utilization=util),\n              checkpoints={name: dict(path=capture["checkpoint"], sha256=capture["checkpoint_sha256"])\n                           for name, capture in captures.items()},\n              rows=rows, training_stress=stress, summary=summary,\n              limitations=["Frozen TRAIN8 plus largest-pair scenes, serial native predict batch1, two warmups/three readings.",\n                           "Separate native loss/backward/AdamW stress batch2; trained weights, fresh native optimizer warmed twice.",\n                           "Stress updates remain memory-only; original checkpoints are not overwritten or resumed.",\n                           "Candidate then parent order does not isolate transient hardware effects; descriptive p95 only.",\n                           "One trained checkpoint per method; cost is not causal efficacy, equivalence or Pareto dominance."])\nPath(P["output"]).write_text(json.dumps(result), encoding="utf-8")\n'
files = [{'path': 'AdaRES/ipdn/model_paper5/adares_y33_token_attention/__init__.py', 'sha256': '8014a039f2388c8ca57692438985474724a17785186036e5208771b856072722'}, {'path': 'AdaRES/ipdn/model_paper5/adares_y33_token_attention/backbone.py', 'sha256': '1eb4ac3483961e708c23b0abad396c181dbf38c56fcca559d88b9622af46bafd'}, {'path': 'AdaRES/ipdn/model_paper5/adares_y33_token_attention/dec.py', 'sha256': 'b035da11511099dc0f764540b825bf129ac747a5c7c42f8aaf991b299dce7849'}, {'path': 'AdaRES/ipdn/model_paper5/adares_y33_token_attention/ipdn.py', 'sha256': '63c8f30bda20300d98d3d9a8a6478fc1a841cbaa3b334ee71688711e06375d97'}, {'path': 'AdaRES/ipdn/model_paper5/adares_y33_token_attention/loss.py', 'sha256': '4aa2818948ebfd9fe416b3b310a053384508ef92c3b67831833fece560523084'}, {'path': 'AdaRES/ipdn/model_paper5/adares_y33_token_attention/sample_model.py', 'sha256': '03fd683acc6d49d9b53e634b42bd150a3259a1a15c7dc8fe2badf115870a345b'}, {'path': 'AdaRES/configs_song/model_paper5/adares_y33_token_attention_res.yaml', 'sha256': '1a170434f63da98e10f59c5b17473cde5cf3ff6be0e4381e2771f322853ffa03'}]


class Identity(ast.NodeTransformer):
    def visit_Assign(self, node):
        if any(isinstance(t, ast.Name) and t.id == "source_manifest" for t in node.targets):
            return ast.parse("source_manifest=" + repr(
                [(r["path"][7:], r["sha256"]) for r in files])).body[0]
        return self.generic_visit(node)

    def visit_Constant(self, node):
        if isinstance(node.value, str):
            return ast.copy_location(ast.Constant(value=node.value.replace(
                "Y31", "Y33").replace("y31", "y33").replace("66677", "64797").replace(
                "5f2489de78196e8d89c004e452a665c0946f2a94",
                "b49b744dc2943a38ab4c3aeb788acc6a2cb90011")), node)
        if node.value == 164763271:
            return ast.copy_location(ast.Constant(value=164958087), node)
        return node


tree = ast.fix_missing_locations(Identity().visit(ast.parse(source)))
exec(compile(tree, "probe_y33_trained_cost", "exec"), globals())
